import { createServer } from "node:http";
import * as client from "@prometheus-io/client";
import { registry } from "./metrics.js";

export const startMetricsServer = (port = 9464) =>
  createServer(async (req, res) => {
    if (req.url !== "/metrics") {
      res.writeHead(404).end();
      return;
    }
    const body = await registry.metrics();
    res.writeHead(200, { "content-type": client.contentType }).end(body);
  }).listen(port);

import type { Point } from "./types.js"; // [name, labels, value, timestampMs]

const line = ([name, labels, value, ts]: Point): string => {
  const pairs = Object.entries(labels).map(([k, v]) => `${k}="${v}"`).join(",");
  return `${name}{${pairs}} ${value} ${ts}`;
};

export const writePoints = async (baseUrl: string, token: string, points: Point[]): Promise<void> => {
  const res = await fetch(`${baseUrl}/api/v1/import/prometheus`, {
    method: "POST",
    headers: { authorization: `Bearer ${token}`, "content-type": "text/plain" },
    body: points.map(line).join("\n") + "\n",
  });
  if (!res.ok) throw new Error(`VictoriaMetrics answered ${res.status}: ${await res.text()}`);
};
